package com.regsco.compras;
import org.junit.*;
import static org.junit.Assert.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import android.graphics.*;
import android.database.Cursor;
import java.io.*;
import java.time.LocalDate;
import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class NewFeaturesTest {
 @Test public void backgroundIsOpaqueAndStableAcrossRedraws(){for(int t=0;t<3;t++){ThemeSkin.Backdrop d=new ThemeSkin.Backdrop(t);d.setBounds(0,0,393,851);Bitmap a=Bitmap.createBitmap(393,851,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(393,851,Bitmap.Config.ARGB_8888);a.eraseColor(Color.WHITE);b.eraseColor(Color.WHITE);d.draw(new Canvas(a));d.draw(new Canvas(b));assertTrue("Theme "+t+" changed on redraw",a.sameAs(b));assertEquals(255,Color.alpha(b.getPixel(10,10)));a.recycle();b.recycle();}}
 @Test public void parsesTwoLineReceiptAndSkipsTotals(){var rows=ReceiptParser.parse("001 7891234567890 ARROZ 1KG\n2 UN X 5,99 11,98\nTOTAL 11,98\nCNPJ 12.123.123/0001-00");assertEquals(1,rows.size());assertEquals("ARROZ 1KG",rows.get(0).name);assertEquals("2",rows.get(0).quantity);assertEquals("5,99",rows.get(0).price);}
 @Test public void preservesWeightedLotTotalAndDiscount(){var rows=ReceiptParser.parse("CARNE BOVINA\n0,532 KG X 34,99 18,61\nARROZ\n2 UN X 5,00 9,00");assertEquals(2,rows.size());assertEquals("1",rows.get(0).quantity);assertEquals("lote 0,532 kg",rows.get(0).unit);assertEquals(1861,Money.parse(rows.get(0).price));assertEquals(100,Money.parse(rows.get(1).discount));}
 @Test public void noteImportIsAtomicAndDuplicateSafe()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).create().get();try{var row=new ReceiptParser.Row("Arroz","2","un","5,00");var rows=Arrays.asList(row);String hash=ReceiptParser.fingerprint("nota de teste");long id=ReceiptReview.insert(a,rows,"Loja",LocalDate.of(2026,10,28),1000,hash,"nota de teste");a.month=10;a.year=2026;assertEquals(1000,a.spent());try{ReceiptReview.insert(a,rows,"Loja",LocalDate.of(2026,10,28),1000,hash,"nota de teste");fail();}catch(IllegalStateException expected){}assertEquals(1000,a.spent());assertTrue(PriceHistory.describe(a.db,"Arroz","","un","",600,-1).contains("mais caro"));assertTrue(PriceHistory.describe(a.db,"Arroz","","un","",400,-1).contains("mais barato"));assertTrue(PriceHistory.describe(a.db,"Arroz","","kg","",400,-1).startsWith("Sem compra"));assertTrue(PriceHistory.describe(a.db,"Arroz","","un","",400,id).startsWith("Sem compra"));}finally{a.db.close();}}
 @Test public void photosSurviveBackup()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).create().get();try{Bitmap bitmap=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.GREEN);String data=ProductPhotos.encode(bitmap);a.db.execSQL("INSERT INTO pantry(name,quantity,image_data) VALUES('Arroz',3,?)",new Object[]{data});ByteArrayOutputStream out=new ByteArrayOutputStream();BackupIO.write(a.db,out);File f=File.createTempFile("backup-photo",".db");f.delete();var staged=BackupIO.stage(a.db,new ByteArrayInputStream(out.toByteArray()),f);try(Cursor c=staged.rawQuery("SELECT image_data FROM pantry",null)){assertTrue(c.moveToFirst());assertNotNull(ProductPhotos.decode(c.getString(0),60));}staged.close();f.delete();}finally{a.db.close();}}
 @Test public void automaticImagesMatchCommonNames(){assertEquals("rice",ProductPhotos.key("Arroz branco"));assertEquals("pasta",ProductPhotos.key("Macarrão"));assertEquals("sugar",ProductPhotos.key("Açúcar"));assertEquals("salt",ProductPhotos.key("Sal refinado"));assertEquals("",ProductPhotos.key("Salada"));}
 @Test public void onlineExcludesForeignStoreAndInvalidPrice()throws Exception{org.json.JSONObject p=new org.json.JSONObject("{\"name\":\"Arroz 1kg\",\"objectID\":\"1\",\"market_id\":\"a\",\"for_sale\":true,\"sale_price\":4.99}");org.json.JSONArray hits=new org.json.JSONArray().put(p).put(new org.json.JSONObject(p.toString()).put("market_id","b"));var offers=OnlinePricesActivity.parseMix(new org.json.JSONObject().put("hits",hits),"a","Loja");assertEquals(1,offers.size());assertEquals(499,offers.get(0).price);assertFalse(OnlinePricesActivity.allowed("https://mateusmais.com.br.evil.example"));assertFalse(OnlinePricesActivity.allowed("file:///tmp/image"));}
}
